// Import of required libraries
import { test, expect, SkyrampClient } from '@skyramp/skyramp';
import {
    MEMBER_PASSWORD,
    MEMBER_USERNAME,
    createCollectionMember,
    deleteCollectionMember,
    getCollectionMembers,
    resolveUserId,
    signInAs,
    transferCollection,
} from './skyrampUtils';

test('testIntegration', async ({ playwright }) => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const { userId: ownerUserId, usersPostResponse } = await resolveUserId(client);
    // The account that owns the collection under test is registered on the first run and
    // already present on every later one; both outcomes are asserted for what they are.
    if (usersPostResponse.statusCode === 400) {
        expect(JSON.parse(usersPostResponse.responseBody).response, 'the secondary account is already registered')
            .toBe("Email or Username already exists.");
    } else {
        expect(usersPostResponse.statusCode, 'status code').toBe(201);
    }
    const collectionName = `isolation-${Date.now()}`;

    // The collection under test belongs to the other account from the moment it is created, so
    // the caller this run authenticates as never owned it and was never a member of it.
    const owner = await signInAs(playwright, MEMBER_USERNAME, MEMBER_PASSWORD);

    try {
        const ownerCreateResponse = await owner.post("/api/v1/collections", {
            data: { color: "#0ea5e9", description: "", isPublic: false, members: [], name: collectionName },
        });
        const collectionsPostResponse = { statusCode: ownerCreateResponse.status() };
        expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
        const createdCollection = (await ownerCreateResponse.json()).response;
        const collectionId = Number(createdCollection.id);
        expect(Number(createdCollection.ownerId), 'the collection belongs to the other account').toBe(ownerUserId);
        expect(createdCollection.name, 'name echoes the value the request sent').toBe(collectionName);
        expect(createdCollection.color, 'color echoes the value the request sent').toBe("#0ea5e9");
        expect(createdCollection.isPublic, 'isPublic echoes the value the request sent').toBe(false);
        expect(collectionId, 'the collection id the server assigned').toBeGreaterThan(0);

        try {
            // The accepted request the refusals below are measured against.
            const ownerList = await owner.get(`/api/v1/collections/${collectionId}/members`);
            expect(ownerList.status(), 'the collection owner can list its members').toBe(200);
            const ownerMembers = (await ownerList.json()).response;
            expect(ownerMembers, 'the new collection has no members').toEqual([]);
            expect(ownerMembers.length, 'the new collection has no members').toBe(0);
            expect(ownerMembers[0], 'the new collection has no first member').toBeUndefined();

            // Read the members of a collection this caller does not own.
            const membersGetResponse = await getCollectionMembers(client, collectionId, 403);
            expect(membersGetResponse.statusCode, 'status code').toBe(403);
            expect(JSON.parse(membersGetResponse.responseBody).response, 'the refusal says why')
                .toBe("Only the owner can manage members.");

            // Invite into a collection this caller does not own.
            const membersPostResponse = await createCollectionMember(
                client, collectionId, { email: "no-such-user@example.com" }, 403,
            );
            expect(membersPostResponse.statusCode, 'status code').toBe(403);
            expect(JSON.parse(membersPostResponse.responseBody).response, 'the invite refusal says why')
                .toBe("Only the owner can manage members.");

            // Remove a member from a collection this caller does not own.
            const membersDeleteResponse = await deleteCollectionMember(client, collectionId, ownerUserId, 403);
            expect(membersDeleteResponse.statusCode, 'status code').toBe(403);
            expect(JSON.parse(membersDeleteResponse.responseBody).response, 'the removal refusal says why')
                .toBe("Only the owner can manage members.");

            // Take ownership of a collection this caller does not own.
            const transferPostResponse = await transferCollection(client, collectionId, { toUserId: ownerUserId }, 403);
            expect(transferPostResponse.statusCode, 'status code').toBe(403);
            expect(JSON.parse(transferPostResponse.responseBody).response, 'the transfer refusal says why')
                .toBe("Only the owner can transfer ownership.");

            // Back as the owner: the four refused calls changed nothing.
            const stateAfter = await owner.get(`/api/v1/collections/${collectionId}/members`);
            expect(stateAfter.status(), 'the owner can still list the members').toBe(200);
            const membersAfterRefusals = (await stateAfter.json()).response;
            expect(membersAfterRefusals, 'the refused calls added no member').toEqual([]);
            expect(membersAfterRefusals[0], 'the refused calls added no first member').toBeUndefined();
            const collectionAfter = await owner.get(`/api/v1/collections/${collectionId}`);
            expect(collectionAfter.status(), 'the owner can still read the collection').toBe(200);
            const collectionAfterBody = (await collectionAfter.json()).response;
            expect(Number(collectionAfterBody.ownerId),
                'the refused transfer left ownership where it was').toBe(ownerUserId);
            expect(collectionAfterBody.name, 'the refused calls left the collection name alone').toBe(collectionName);
        } finally {
            // Runs whether the assertions above pass or fail, so the collection this test
            // created is always removed.
            const ownerDeleteResponse = await owner.delete(`/api/v1/collections/${collectionId}`);
            const collectionsCollectionsDeleteResponse = { statusCode: ownerDeleteResponse.status() };
            expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
        }
    } finally {
        await owner.dispose();
    }
});
